// Подключение библиотек
#include <Arduino.h>
#include <RGBmatrixPanel.h>

// Определение выводов подключения матрицы
#define R0_PIN 24
#define G0_PIN 25
#define B0_PIN 26
#define R1_PIN 27
#define G1_PIN 28
#define B1_PIN 29
#define A_PIN  30
#define B_PIN  31
#define C_PIN  32
#define D_PIN  33
#define CLK_PIN 34
#define LAT_PIN 35
#define OE_PIN  36

// Инициализация матрицы
RGBmatrixPanel matrix(A_PIN, B_PIN, C_PIN, D_PIN, CLK_PIN, LAT_PIN, OE_PIN,
                      R0_PIN, G0_PIN, B0_PIN, R1_PIN, G1_PIN, B1_PIN, false);

// Графический буфер
uint16_t frameBuffer[64 * 32];

// Текущая яркость
uint8_t brightness = 128;

// Изображения (примеры)
const uint16_t image1[] PROGMEM = { /* данные изображения 1 */ };
const uint16_t image2[] PROGMEM = { /* данные изображения 2 */ };
const uint16_t image3[] PROGMEM = { /* данные изображения 3 */ };
const uint16_t image4[] PROGMEM = { /* данные изображения 4 */ };

// Указатели на изображения
const uint16_t* images[] = { image1, image2, image3, image4 };
uint8_t currentImage = 0;

void setup() {
    // Инициализация матрицы
    matrix.begin();

    // Установка начальной яркости
    matrix.setBrightness(brightness);

    // Загрузка первого изображения
    loadImage(currentImage);
}

void loop() {
    // Вывод текущего кадра
    displayFrame();

    // Проверка кнопки смены изображения (пример)
    if (digitalRead(BUTTON_PIN) == LOW) {
        delay(50); // антидребезг
        if (digitalRead(BUTTON_PIN) == LOW) {
            currentImage = (currentImage + 1) % 4;
            loadImage(currentImage);
            while (digitalRead(BUTTON_PIN) == LOW);
        }
    }
}

// Загрузка изображения в буфер
void loadImage(uint8_t index) {
    for (uint16_t i = 0; i < 64 * 32; i++) {
        frameBuffer[i] = pgm_read_word(&images[index][i]);
    }
}

// Вывод кадра на матрицу
void displayFrame() {
    for (uint8_t row = 0; row < 32; row++) {
        for (uint8_t col = 0; col < 64; col++) {
            uint16_t color = frameBuffer[row * 64 + col];
            matrix.drawPixel(col, row, color);
        }
    }
    matrix.swapBuffers(false);
}
